import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

it('sums usage from a tool call and its final provider call [specs/hal-engine-config-hooks/spec.md#9]', async () => {
  const rounds: MessageChunk[][] = [
    [
      {type: 'tool_use', toolCall: {id: 'lookup-1', name: 'lookup', input: {}}},
      {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 11, outputTokens: 2, totalTokens: 13}},
    ],
    [
      {type: 'text', text: 'Done.'},
      {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 23, outputTokens: 5, totalTokens: 28}},
    ],
  ];
  let round = 0;
  const provider: AIProvider = {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield* rounds[round++] ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const tools = new ToolRegistry();
  tools.register({name: 'lookup', description: 'Look up a value.', inputSchema: {type: 'object'}}, async () => 'found');
  let reported: UsageMetadata | undefined;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Usage test.'}), tools, {
    hooks: {
      afterModelResponse: async (_session, _text, usage) => {
        reported = usage;
      },
    },
  });
  const session: ChatSession = {
    sessionId: 'usage-session',
    userId: 'usage-user',
    entries: [{role: 'user', content: 'Look it up.', timestamp: '2026-01-01T00:00:00.000Z'}],
