import {addTurnUsage} from './turnUsage.js';

describe('[specs/hal-engine-config-hooks/spec.md#10]', () => {
  it('counts only provider rounds with usage and leaves an unreported turn undefined', () => {
    const first = addTurnUsage(undefined, undefined);
    const second = addTurnUsage(first, {inputTokens: 2, outputTokens: 3, totalTokens: 5});
    const third = addTurnUsage(second, undefined);
    const fourth = addTurnUsage(third, {inputTokens: 7, outputTokens: 11, totalTokens: 18});

    expect(first).toBeUndefined();
    expect(third).toEqual({inputTokens: 2, outputTokens: 3, totalTokens: 5});
    expect(fourth).toEqual({inputTokens: 9, outputTokens: 14, totalTokens: 23});
  });
});
import type {UsageMetadata} from '../types/ai.js';

/** Add one provider call's reported usage to the user turn's total. */
export function addTurnUsage(
  total: UsageMetadata | undefined,
  round: UsageMetadata | undefined
): UsageMetadata | undefined {
  if (!round) return total;
  if (!total) return {...round};
  return {
    inputTokens: total.inputTokens + round.inputTokens,
    outputTokens: total.outputTokens + round.outputTokens,
    totalTokens: total.totalTokens + round.totalTokens,
  };
}

